ALTER TABLE public.practical_templates ADD COLUMN IF NOT EXISTS reference_image text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS reference_caption text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS observation_rows jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS inference text NOT NULL DEFAULT '';
DROP POLICY IF EXISTS "Authenticated read templates" ON public.practical_templates;
CREATE POLICY "Read published templates" ON public.practical_templates FOR SELECT TO authenticated USING (status = 'Published' OR public.has_role(auth.uid(), 'faculty') OR public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Faculty manage practical catalog" ON public.practicals FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'faculty') OR public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'faculty') OR public.has_role(auth.uid(), 'admin'));
CREATE OR REPLACE FUNCTION public.save_journal_template(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
BEGIN
IF NOT (public.has_role(auth.uid(), 'faculty') OR public.has_role(auth.uid(), 'admin')) THEN RAISE EXCEPTION 'Only faculty and administrators can edit shared journal templates.'; END IF;
IF coalesce(trim(payload->>'code'),'') = '' OR coalesce(trim(payload->>'title'),'') = '' THEN RAISE EXCEPTION 'Code and title are required.'; END IF;
IF payload->>'status' NOT IN ('Draft','Published') THEN RAISE EXCEPTION 'Invalid template status.'; END IF;
INSERT INTO public.practicals(code,seq,title,category,type,active) VALUES (payload->>'code',(payload->>'seq')::int,payload->>'title',payload->>'category',payload->>'type',true) ON CONFLICT(code) DO UPDATE SET seq=EXCLUDED.seq,title=EXCLUDED.title,category=EXCLUDED.category,type=EXCLUDED.type;
INSERT INTO public.practical_templates(code,seq,title,category,type,author,version,status,aim,principle,apparatus,procedure,formula,columns,viva_questions,max_marks,penalty,req_diagram,req_calculations,req_viva,reference_image,reference_caption,observation_rows,inference,updated_at)
VALUES(payload->>'code',(payload->>'seq')::int,payload->>'title',payload->>'category',payload->>'type',payload->>'author',payload->>'version',payload->>'status',payload->>'aim',payload->>'principle',payload->>'apparatus',payload->>'procedure',payload->>'formula',payload->'columns',payload->'viva_questions',(payload->>'max_marks')::int,(payload->>'penalty')::int,(payload->>'req_diagram')::boolean,(payload->>'req_calculations')::boolean,(payload->>'req_viva')::boolean,payload->>'reference_image',payload->>'reference_caption',payload->'observation_rows',payload->>'inference',now())
ON CONFLICT(code) DO UPDATE SET seq=EXCLUDED.seq,title=EXCLUDED.title,category=EXCLUDED.category,type=EXCLUDED.type,author=EXCLUDED.author,version=EXCLUDED.version,status=EXCLUDED.status,aim=EXCLUDED.aim,principle=EXCLUDED.principle,apparatus=EXCLUDED.apparatus,procedure=EXCLUDED.procedure,formula=EXCLUDED.formula,columns=EXCLUDED.columns,viva_questions=EXCLUDED.viva_questions,max_marks=EXCLUDED.max_marks,penalty=EXCLUDED.penalty,req_diagram=EXCLUDED.req_diagram,req_calculations=EXCLUDED.req_calculations,req_viva=EXCLUDED.req_viva,reference_image=EXCLUDED.reference_image,reference_caption=EXCLUDED.reference_caption,observation_rows=EXCLUDED.observation_rows,inference=EXCLUDED.inference,updated_at=EXCLUDED.updated_at;
END; $$;
REVOKE ALL ON FUNCTION public.save_journal_template(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_journal_template(jsonb) TO authenticated;